import {Ecosystem,SPECIES,DAY,clamp} from './simulation.js';
import {World} from './world.js';
import {TRAITS,patternName} from './genetics.js';
import {Soundscape} from './sound.js';
import {NotificationQueue} from './notifications.js';
import {MATERIALS,ACTION_NAMES} from './culture.js';
const $=id=>document.getElementById(id),KEY='vespera-world-v2';
let sim,world,tool='observe',speed=1,paused=false,selected=null,following=false,zen=false,lastUI=0,accum=0,last=performance.now(),lastRender=0,toastTimer,saveTimer=0,audio=new Soundscape(),qualityMode='auto',fpsFrames=0,fpsClock=0,fpsMeasured=0,qualityClock=0,renderDue=0,simMs=0,journalFilter='all',notices=[];
function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return;const s=JSON.parse(raw);if((s.version===2||s.version===3||s.version===4)&&Array.isArray(s.creatures)&&s.creatures.length<=128&&s.climate&&Number.isFinite(s.time)){if(s.version===2&&!localStorage.getItem('vespera-v1-backup'))localStorage.setItem('vespera-v1-backup',raw);return s;}}catch{}return undefined;}
const notifications=new NotificationQueue($('notifications'),{onSelect:id=>selectCreature(id)});
function toast(msg){notifications.push({text:msg,title:'Observatorio'});}
function save(){try{localStorage.setItem(KEY,JSON.stringify(sim.snapshot()));$('save-status').textContent='Tu mundo se guarda en este dispositivo';return true;}catch{$('save-status').textContent='No se pudo guardar en este navegador';return false;}}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function ageText(age){return age<1?Math.max(1,Math.round(age*24))+' h':Math.floor(age)+' días';}
function eventAge(time){const d=(sim.time-time)/DAY;return d<.05?'ahora':d<1?'hace '+Math.max(1,Math.floor(d*24))+' h':'día '+(Math.floor(time/DAY)+1);}
function getCreature(){return sim.creatures.find(c=>c.id===selected)||sim.archive.find(c=>c.id===selected);}
function selectCreature(id,follow=false){const c=sim.creatures.find(c=>c.id===id)||sim.archive.find(c=>c.id===id);if(!c)return;selected=id;c.named=true;world.select(id,follow);following=follow;$('detail').hidden=false;$('creature-name').value=c.name;updateDetail();updateSpecies();save();}
function closeDetail(){selected=null;following=false;world.select(null);$('detail').hidden=true;}
function formatGene(key,v){return key==='hue'?(v>=0?'+':'')+Math.round(v*360)+'°':key==='pattern'?Math.round(v*100)+'%':v.toFixed(2)+'×';}
function updateDetail(){if(selected===null)return;const c=getCreature();if(!c){closeDetail();return;}const alive=c.died===undefined,s=SPECIES[c.species],g=c.dna.traits;$('detail-species').textContent=s.name.toUpperCase()+' · '+(c.sex==='F'?'HEMBRA ♀':'MACHO ♂');if(document.activeElement!==$('creature-name'))$('creature-name').value=c.name;$('detail-state').textContent=alive?(c.age<3?'Cría · ':'')+c.state:'Su ciclo terminó';$('detail-description').textContent=s.latin+' · '+s.description;$('detail-age').textContent=ageText(c.age)+' / '+Math.round(c.life)+' d';$('detail-generation').textContent=String(c.generation).padStart(2,'0');$('detail-cells').textContent=alive?(world.cellCounts.get(c.id)||'…')+' / 300':'—';$('energy-value').textContent=alive?Math.round(clamp(c.energy,0,100))+'%':'0%';$('energy-bar').style.width=(alive?clamp(c.energy,0,100):0)+'%';$('detail-lineage').textContent=alive?(c.mother?'Madre: '+c.motherName+' · Padre: '+(c.fatherName||'Sin registro')+'.':'Linaje fundador. Sin progenitores registrados.'):'Día '+(Math.floor(c.died/DAY)+1)+': '+c.name+' '+c.cause+'. Sus restos vuelven al ecosistema.';
 const stats=[['Salud',alive?Math.round(c.health)+'%':'0%'],['Dieta',s.diet],['Hábitat',s.habitat==='water'?'Acuático':s.legs===2?'Terrestre · bípedo':'Terrestre'],['Velocidad',(s.speed*g.speed).toFixed(2)+' u/s'],['Descendientes',c.children],['Alimentos',c.foodEaten],['Recorrido',Math.round(c.distance)+' u'],['Madurez',Math.round(clamp(c.age/3,0,1)*100)+'%'],['Reproducción',c.pregnancy?'Gestando':c.stage?'En pareja':c.cooldown>0?'Recuperándose':c.age<3?'Juvenil':'Disponible']];$('technical-stats').innerHTML=stats.map(([k,v])=>`<div><span>${k}</span><b>${escapeHtml(v)}</b></div>`).join('');$('gestation').hidden=!c.pregnancy;if(c.pregnancy)$('gestation').textContent=(s.habitat==='water'?'Puesta':'Gestación')+' · '+Math.round((1-c.pregnancy.remaining/c.pregnancy.total)*100)+'% · Padre: '+c.pregnancy.fatherName;
 $('dna-seed').textContent=c.dna.seed.toString(16).toUpperCase().padStart(8,'0');$('genetic-pattern').textContent=patternName(c.dna)+' · '+(c.mother?'Un alelo de cada progenitor.':'Dos alelos fundadores.')+' La semilla define sus detalles individuales.';$('allele-a').textContent=c.mother?'Madre':'Alelo A';$('allele-b').textContent=c.father?'Padre':'Alelo B';$('gene-rows').innerHTML=Object.entries(TRAITS).map(([key,t])=>`<tr><td>${t.name}</td><td>${formatGene(key,c.dna.alleles[key][0])}</td><td>${formatGene(key,c.dna.alleles[key][1])}</td><td>${formatGene(key,g[key])}</td></tr>`).join('');$('mutation-list').innerHTML=c.dna.mutations.length?'<b>Mutaciones registradas</b><br>'+c.dna.mutations.slice(-5).map(m=>escapeHtml(TRAITS[m.trait].name+' · '+m.origin+' · alelo '+(m.allele===0?'materno':'paterno'))).join('<br>'):'Sin mutaciones nuevas registradas. Sus variantes también pueden ser heredadas.';$('follow').textContent=following?'Dejar de seguir':'Seguir su camino';$('follow').classList.toggle('active',following);$('follow').disabled=!alive;$('animal-call').disabled=!alive;const m=c.mind;$('mind-summary').innerHTML=m?'<b>Aprendizaje situado</b><br>'+m.trials+' experiencias · '+m.successes+' resultados favorables<br>'+m.learnedFrom+' aprendizajes sociales · '+m.placed+' piezas colocadas<br>Última acción: '+(ACTION_NAMES[m.lastAction]||'Explorar')+'<br>Transporta: '+(m.carrying?MATERIALS[m.carrying.type].name:'Nada')+'<br>Cobijo local: '+Math.round((c.shelter||0)*100)+'%':'';
}
function updateSpecies(){const counts=SPECIES.map(s=>sim.creatures.filter(c=>c.species===s.id).length);$('species-list').innerHTML=SPECIES.map((s,i)=>`<button class="species-card" data-species="${s.id}" title="${escapeHtml(s.description)}"><span class="species-orb" style="--color:${s.color}"></span><span><b>${s.name}</b><small>${s.habitat==='water'?'Acuático · aletas':s.diet+' · '+s.legs+' patas'}</small></span><span class="species-number">${counts[i]}</span></button>`).join('');const named=[...sim.creatures.filter(c=>c.named),...sim.archive.filter(c=>c.named)].slice(0,35);$('tracked-list').innerHTML=named.length?named.map(c=>`<button class="tracked-person" data-creature="${c.id}">${escapeHtml(c.name)}<span>${c.died!==undefined?'Ciclo completo':ageText(c.age)}</span></button>`).join(''):'<p class="tracked-empty">Tocá una criatura en el jardín para conocerla. Su historia aparecerá aquí.</p>';}
function updateUI(){const counts=new Set(sim.creatures.map(c=>c.species));$('day').textContent='Día '+(Math.floor(sim.time/DAY)+1);$('season').textContent=sim.seasonName;$('population').textContent=sim.creatures.length;$('species-count').textContent=counts.size;$('birth-count').textContent=sim.births;
for(const key of ['moisture','temperature','fertility']){const el=$(key),val=sim.climate[key];if(document.activeElement!==el)el.value=val;el.style.setProperty('--val',((val-Number(el.min))/(Number(el.max)-Number(el.min))*100)+'%');$(key+'-value').textContent=Math.round(val)+(key==='temperature'?'°':'%');}
const descriptions={'Lluvia':'La lluvia alimenta el suelo y despierta las semillas.','Sequía':'La tierra se seca. Los brotes necesitan agua.','Frío':'El frío ralentiza el crecimiento de los brotes.','Calor':'El calor aumenta el hambre y evapora el agua.','Calma':sim.climate.fertility<25?'Pocos nutrientes: los nuevos brotes crecen lentamente.':'La tierra húmeda invita a brotar.'};$('weather-note').textContent=descriptions[sim.weather];$('weather-icon').textContent=sim.weather==='Lluvia'?'☂':sim.weather==='Frío'?'❄':'☀';
$('events').innerHTML=sim.events.slice(0,4).map(e=>`<div class="event"><span class="event-icon">${e.icon}</span><div><p>${escapeHtml(e.text)}</p><small>${eventAge(e.time)}</small></div></div>`).join('');const h=sim.history.length?sim.history:[sim.creatures.length,sim.creatures.length],min=Math.max(0,Math.min(...h)-5),max=Math.max(...h)+5,coords=h.map((v,i)=>[i/(h.length-1||1)*260,40-(v-min)/(max-min)*32]);const path=coords.map((v,i)=>(i?'L':'M')+v[0].toFixed(1)+' '+v[1].toFixed(1)).join(' ');$('chart-line').setAttribute('d',path);$('chart-area').setAttribute('d',path+' L260 46 L0 46 Z');$('scene-description').textContent=sim.creatures.length===0?'El jardín espera. Un ciclo ha terminado.':sim.rain>0?'La lluvia cambia el ritmo del jardín.':sim.births>0?sim.births+' nuevas vidas. Ninguna idéntica a la anterior.':'Todo comienza con una célula.';$('plant-count').textContent=sim.food.length+' plantas · 5 variedades';$('nutrient-count').textContent=Math.round(sim.nutrientsReturned)+' nutrientes devueltos';$('land-size').textContent='Jardín · '+((sim.radius/24)**2).toFixed(1)+'×';$('land-capacity').textContent=sim.capacity+' habitantes posibles';$('expand').disabled=true;$('expand').textContent=sim.expansions>=3?'Frontera máxima':'Exploración autónoma';$('culture-summary').textContent=sim.culture.blocks.length+' piezas · '+sim.culture.groups.length+' agrupaciones';$('discovery-progress').textContent='Exploración de frontera: '+Math.round(Math.min(1,sim.culture.expansionPressure/12)*100)+'%';updateDetail();if(!$('life').hidden)updateSpecies();if($('journal-dialog').open)updateJournal();if($('performance-dialog').open)updatePerformance();if($('culture-dialog').open)updateCulture();}
function chooseTool(next){tool=next;document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));$('tool-hint').textContent={observe:'Elegí una criatura para conocer su historia',feed:'Tocá la tierra para sembrar alimento',rain:'Tocá el jardín para atraer una lluvia suave',mutate:'Tocá cerca de una criatura para cambiar un rasgo heredable'}[tool];$('world').style.cursor=tool==='observe'?'grab':'crosshair';}
function togglePause(){paused=!paused;$('pause').textContent=paused?'▷':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Reanudar simulación':'Pausar simulación');$('pause').title=paused?'Reanudar (espacio)':'Pausa (espacio)';toast(paused?'El mundo descansa.':'La vida continúa.');}
function toggleZen(){zen=!zen;document.body.classList.toggle('zen-mode',zen);$('exit-zen').hidden=!zen;}
function setTab(tab){for(const id of ['ecosystem','life']){$(id).hidden=id!==tab;$('tab-'+id).classList.toggle('active',id===tab);$('tab-'+id).setAttribute('aria-selected',String(id===tab));}if(tab==='life')updateSpecies();}
function rename(){const c=getCreature();if(!c)return;const name=$('creature-name').value.trim().slice(0,28);if(!name){$('creature-name').value=c.name;return;}const old=c.name;c.name=name;c.named=true;for(const child of [...sim.creatures,...sim.archive]){if(child.parent===c.id)child.parentName=name;if(child.otherParent===c.id)child.otherParentName=name;if(child.mother===c.id)child.motherName=name;if(child.father===c.id)child.fatherName=name;if(child.pregnancy?.father===c.id)child.pregnancy.fatherName=name;}save();updateSpecies();if(old!==name)toast('Ahora conocés a '+name+'.');$('creature-name').blur();}
function bindUI(){document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>chooseTool(b.dataset.tool)));document.querySelectorAll('[data-speed]').forEach(b=>b.addEventListener('click',()=>{speed=Number(b.dataset.speed);document.querySelectorAll('[data-speed]').forEach(el=>el.classList.toggle('active',el===b));}));$('pause').onclick=togglePause;$('zen').onclick=toggleZen;$('exit-zen').onclick=toggleZen;$('bones').onclick=()=>{$('bones').classList.toggle('active',world.toggleSkeleton());toast(world.skeleton?'Esqueleto visible: columna y patas con IK.':'Volviste a la piel celular.');};$('zoom-in').onclick=()=>world.zoom(.8);$('zoom-out').onclick=()=>world.zoom(1.25);$('home-view').onclick=()=>{following=false;world.home();updateDetail();};$('tab-ecosystem').onclick=()=>setTab('ecosystem');$('tab-life').onclick=()=>setTab('life');for(const key of ['moisture','temperature','fertility']){$(key).addEventListener('input',e=>{sim.setClimate(key,Number(e.target.value));updateUI();});$(key).addEventListener('change',()=>save());}
$('species-list').onclick=e=>{const b=e.target.closest('[data-species]');if(!b)return;const id=Number(b.dataset.species),c=sim.creatures.find(c=>c.species===id);toast(SPECIES[id].description);if(c)selectCreature(c.id,true);};$('tracked-list').onclick=e=>{const b=e.target.closest('[data-creature]');if(b)selectCreature(Number(b.dataset.creature),sim.creatures.some(c=>c.id===Number(b.dataset.creature)));};$('close-detail').onclick=closeDetail;$('rename').onclick=rename;$('creature-name').addEventListener('keydown',e=>{if(e.key==='Enter')rename();});$('creature-name').addEventListener('change',rename);$('follow').onclick=()=>{following=!following;world.select(selected,following);if(!following)world.home();updateDetail();};$('help').onclick=()=>$('welcome').showModal();$('close-help').onclick=()=>$('welcome').close();$('start-observing').onclick=()=>$('welcome').close();$('reset').onclick=()=>$('reset-dialog').showModal();$('cancel-reset').onclick=()=>$('reset-dialog').close();$('confirm-reset').onclick=()=>{sim=new Ecosystem();attachEvents();world.sim=sim;world.actors.clear();closeDetail();world.home();accum=0;paused=false;$('pause').textContent='Ⅱ';$('reset-dialog').close();save();updateUI();toast('Otro mundo empieza a respirar.');};$('sound').onclick=toggleSound;$('animal-call').onclick=async()=>{if(!audio.enabled)await toggleSound();audio.call(getCreature(),world.target.x);};$('culture-open').onclick=()=>{updateCulture();$('culture-dialog').showModal();};$('culture-close').onclick=()=>$('culture-dialog').close();$('open-journal').onclick=()=>{updateJournal();$('journal-dialog').showModal();};$('close-journal').onclick=()=>$('journal-dialog').close();$('journal-filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b){journalFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>el.classList.toggle('active',el===b));updateJournal();}};$('journal-list').onclick=e=>{const b=e.target.closest('[data-entity]');if(b&&Number(b.dataset.entity)){selectCreature(Number(b.dataset.entity),false);$('journal-dialog').close();}};$('performance').onclick=()=>{updatePerformance();$('performance-dialog').showModal();};$('close-performance').onclick=()=>$('performance-dialog').close();$('quality-mode').onchange=e=>{qualityMode=e.target.value;if(qualityMode!=='auto')world.setQuality(Number(qualityMode));qualityClock=0;};
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();togglePause();}if(e.key.toLowerCase()==='h')toggleZen();if(e.key==='Escape'){if(zen)toggleZen();else closeDetail();}});window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{save();last=performance.now();accum=0;audio.visibility(document.hidden);fpsClock=0;fpsFrames=0;renderDue=0;});
world.onClick=({id,x,z})=>{if(tool==='observe'){if(id)selectCreature(id);else closeDetail();}else{toast(sim.intervene(tool,x,z));save();updateUI();}};world.onOrbit=()=>{following=false;updateDetail();};}
const eventNames={birth:'Una nueva vida',death:'Un ciclo termina',compost:'Vida que nutre vida',court:'Encuentro',gestation:'Una vida en camino',mutation:'Variación genética',expansion:'El jardín crece'};
function attachEvents(){sim.onEvent=e=>{audio.event(e,sim);if(['birth','death','compost','mutation','gestation','discovery','collective'].includes(e.kind)&&!document.hidden)notifications.push({...e,title:eventNames[e.kind]||'El mundo cambia'});};}
function updateCulture(){const x=sim.culture;$('culture-stats').innerHTML='<p><b>'+x.blocks.length+'</b> piezas colocadas · <b>'+x.groups.length+'</b> agrupaciones observadas</p><p>'+x.totals.collected+' recolecciones · '+x.totals.shared+' intercambios · '+x.totals.contests+' disputas · '+x.totals.learned+' experiencias evaluadas</p><p>Capacidad cognitiva media: '+(sim.creatures.reduce((a,c)=>a+c.dna.traits.cognition,0)/Math.max(1,sim.creatures.length)).toFixed(2)+'×</p>';$('group-list').innerHTML=x.groups.length?x.groups.slice(0,8).map(g=>'<div class=group-row><b>Agrupación '+g.id+'</b><span>'+g.blocks+' piezas · '+g.members+' habitantes cercanos · '+(g.maxLevel+1)+' alturas</span></div>').join(''):'<p>Todavía no hay agrupaciones de cuatro o más piezas conectadas.</p>'; }
function updateJournal(){const events=sim.events.filter(e=>journalFilter==='all'||e.kind===journalFilter||(journalFilter==='court'&&e.kind==='gestation'));$('journal-list').innerHTML=events.length?events.map(e=>`<button class="journal-item" data-entity="${e.entity||0}"><span>${e.icon}</span><div><p>${escapeHtml(e.text)}</p><small>Día ${Math.floor(e.time/DAY)+1} · ${eventNames[e.kind]||'Ecosistema'}</small></div></button>`).join(''):'<p>Todavía no hay acontecimientos de este tipo.</p>';}
function updatePerformance(){const info=world.renderer.info.render;$('performance-stats').innerHTML=`<div><b>${fpsMeasured?fpsMeasured.toFixed(0):'…'}</b><span>FPS medidos</span></div><div><b>${world.cellIndex.toLocaleString('es')}</b><span>Esferas visibles</span></div><div><b>${world.renderMs.toFixed(1)} ms</b><span>Preparación y envío CPU</span></div><div><b>${simMs.toFixed(1)} ms</b><span>Simulación CPU por cuadro</span></div><div><b>${info.calls}</b><span>Llamadas de dibujo</span></div><div><b>${['Alta','Equilibrada','Fluida'][world.qualityTier]}</b><span>Calidad actual</span></div>`;}
async function toggleSound(){try{const on=await audio.toggle();$('sound').classList.toggle('active',on);$('sound').setAttribute('aria-label',on?'Silenciar sonidos':'Activar sonidos');$('sound').title=on?'Silenciar sonidos':'Activar sonidos';if(on)toast('Voces del jardín activadas.');}catch{toast('Este navegador no pudo iniciar el sonido.');}}
function advance(realDt,background=false){const started=performance.now();if(!paused){accum=Math.min(8,accum+Math.min(realDt,2)*speed);let n=0;while(accum>=.1&&n<(background?160:8)){sim.step(.1);accum-=.1;n++;if(!background&&performance.now()-started>3)break;}}simMs=performance.now()-started;}
function frame(now){requestAnimationFrame(frame);if(document.hidden){last=now;return;}const wallDt=Math.max(0,(now-last)/1000),realDt=Math.min(.25,wallDt);last=now;advance(realDt);renderDue+=realDt;if(renderDue>=1/60-.0008){world.render(Math.min(.06,(now-lastRender)/1000));lastRender=now;renderDue=Math.max(0,renderDue-1/60);if(renderDue>.06)renderDue=0;fpsFrames++;}fpsClock+=wallDt;qualityClock+=wallDt;if(fpsClock>=2.5){fpsMeasured=fpsFrames/fpsClock;$('performance').textContent=Math.round(fpsMeasured)+' FPS'+(qualityMode==='auto'?' · auto':'');if(qualityMode==='auto'&&qualityClock>6&&fpsMeasured<53&&world.qualityTier<2){world.setQuality(world.qualityTier+1);qualityClock=0;}else if(qualityMode==='auto'&&qualityClock>25&&fpsMeasured>59&&world.renderMs<6&&world.qualityTier>0){world.setQuality(world.qualityTier-1);qualityClock=0;}fpsClock=0;fpsFrames=0;}lastUI+=realDt;saveTimer+=realDt;if(lastUI>.8){lastUI=0;updateUI();}if(saveTimer>12){saveTimer=0;save();}if(!paused)audio.update(now,sim,world.target.x);}
try{sim=new Ecosystem(load());attachEvents();world=new World($('world'),sim);bindUI();world.updateEnvironment();world.render(.016);updateUI();chooseTool('observe');requestAnimationFrame(frame);setInterval(()=>{if(document.hidden){advance(1,true);saveTimer++;if(saveTimer>=12){saveTimer=0;save();}}},1000);$('loading').style.opacity='0';setTimeout(()=>$('loading').hidden=true,900);}catch(e){console.error(e);$('loading-note').textContent='No se pudo iniciar la vista 3D. Probá activar la aceleración gráfica y recargar la página.';$('loading').querySelector('span').textContent='El jardín necesita WebGL';}
